using System;
using System.IO;
using System.Linq;
using System.Text;
using System.Runtime.InteropServices;
using System.Collections.Generic;

namespace kok {
 // SQLite is deliberately isolated here. Values always use bound parameters.
 internal sealed class SqlDb:IDisposable {
  IntPtr db;
  const string Dll="sqlite3.dll";
  [DllImport(Dll,CallingConvention=CallingConvention.Cdecl)] static extern int sqlite3_open(byte[] path,out IntPtr db);
  [DllImport(Dll,CallingConvention=CallingConvention.Cdecl)] static extern int sqlite3_close_v2(IntPtr db);
  [DllImport(Dll,CallingConvention=CallingConvention.Cdecl)] static extern int sqlite3_busy_timeout(IntPtr db,int ms);
  [DllImport(Dll,CallingConvention=CallingConvention.Cdecl)] static extern int sqlite3_prepare_v2(IntPtr db,byte[] sql,int n,out IntPtr statement,IntPtr tail);
  [DllImport(Dll,CallingConvention=CallingConvention.Cdecl)] static extern int sqlite3_bind_text(IntPtr statement,int i,byte[] value,int n,IntPtr destructor);
  [DllImport(Dll,CallingConvention=CallingConvention.Cdecl)] static extern int sqlite3_step(IntPtr statement);
  [DllImport(Dll,CallingConvention=CallingConvention.Cdecl)] static extern int sqlite3_finalize(IntPtr statement);
  [DllImport(Dll,CallingConvention=CallingConvention.Cdecl)] static extern IntPtr sqlite3_column_text(IntPtr statement,int i);
  [DllImport(Dll,CallingConvention=CallingConvention.Cdecl)] static extern int sqlite3_column_bytes(IntPtr statement,int i);
  [DllImport(Dll,CallingConvention=CallingConvention.Cdecl)] static extern int sqlite3_column_count(IntPtr statement);
  [DllImport(Dll,CallingConvention=CallingConvention.Cdecl)] static extern IntPtr sqlite3_serialize(IntPtr db,byte[] schema,out long size,uint flags);
  [DllImport(Dll,CallingConvention=CallingConvention.Cdecl)] static extern IntPtr sqlite3_malloc64(ulong size);
  [DllImport(Dll,CallingConvention=CallingConvention.Cdecl)] static extern void sqlite3_free(IntPtr p);
  [DllImport(Dll,CallingConvention=CallingConvention.Cdecl)] static extern int sqlite3_deserialize(IntPtr db,byte[] schema,IntPtr bytes,long size,long capacity,uint flags);
  [DllImport(Dll,CallingConvention=CallingConvention.Cdecl)] static extern IntPtr sqlite3_backup_init(IntPtr target,byte[] targetName,IntPtr source,byte[] sourceName);
  [DllImport(Dll,CallingConvention=CallingConvention.Cdecl)] static extern int sqlite3_backup_step(IntPtr backup,int pages);
  [DllImport(Dll,CallingConvention=CallingConvention.Cdecl)] static extern int sqlite3_backup_finish(IntPtr backup);
  static byte[] Utf8(string s){return Encoding.UTF8.GetBytes((s??"")+"\0");}
  static void Check(int code){if(code!=0)throw new IOException("本地资料库操作失败，请保留数据和备份后重试。 SQLite: "+code);}
  public SqlDb(string file,byte[] image=null){try{Check(sqlite3_open(Utf8(file),out db));sqlite3_busy_timeout(db,4000);if(image!=null){var memory=sqlite3_malloc64((ulong)image.Length);if(memory==IntPtr.Zero)throw new OutOfMemoryException();Marshal.Copy(image,0,memory,image.Length);int code=sqlite3_deserialize(db,Utf8("main"),memory,image.Length,image.Length,3);if(code!=0){sqlite3_free(memory);Check(code);}}}catch{Dispose();throw;}}
  public List<string[]> Query(string sql,params string[] values){IntPtr statement;Check(sqlite3_prepare_v2(db,Utf8(sql),-1,out statement,IntPtr.Zero));try{for(int i=0;i<values.Length;i++){var bytes=Utf8(values[i]);Check(sqlite3_bind_text(statement,i+1,bytes,bytes.Length-1,new IntPtr(-1)));}var rows=new List<string[]>();int state;while((state=sqlite3_step(statement))==100){var row=new string[sqlite3_column_count(statement)];for(int i=0;i<row.Length;i++){int length=sqlite3_column_bytes(statement,i);var bytes=new byte[length];if(length>0)Marshal.Copy(sqlite3_column_text(statement,i),bytes,0,length);row[i]=Encoding.UTF8.GetString(bytes);}rows.Add(row);}if(state!=101)Check(state);return rows;}finally{sqlite3_finalize(statement);}}
  public void Exec(string sql,params string[] values){Query(sql,values);}
  public byte[] Image(){long size;var memory=sqlite3_serialize(db,Utf8("main"),out size,0);if(memory==IntPtr.Zero||size>256*1024*1024)throw new IOException("资料库过大，未覆盖现有数据。");try{var bytes=new byte[(int)size];Marshal.Copy(memory,bytes,0,bytes.Length);return bytes;}finally{sqlite3_free(memory);}}
  public void Backup(string file){using(var target=new SqlDb(file)){var handle=sqlite3_backup_init(target.db,Utf8("main"),db,Utf8("main"));if(handle==IntPtr.Zero)throw new IOException("资料库备份失败，未执行修改。");try{int code=sqlite3_backup_step(handle,-1);if(code!=101)Check(code);}finally{Check(sqlite3_backup_finish(handle));}}}
  public void Dispose(){if(db!=IntPtr.Zero){sqlite3_close_v2(db);db=IntPtr.Zero;}}
 }
 public sealed class ItemRecord {public string id,path,name,kind,ext,added,opened,modified;public long size;public bool favorite;public double progress,position;}
 internal static class ItemShape {
  public static readonly string[] Core={"id","path","name","kind","ext","added","opened","modified","size","favorite","progress","position","chapter","ownedDocument","agentOperationId","width","height","hasCover","coverVersion"};
  public static readonly Dictionary<string,string[]> Facets=new Dictionary<string,string[]>{{"organization",new[]{"collection","tags","aiCategory","aiSummary","aiFingerprint"}},{"notes",new[]{"notes"}},{"music",new[]{"album","artist","audio"}},{"ai",new[]{"aiChat","aiStudies"}},{"video",new[]{"videoOutline","generatedSubtitles"}},{"editing",new[]{"editDraft"}},{"annotations",new[]{"annotations"}},{"reading",new[]{"chapterTexts","bookmarks"}}};
  public static Dictionary<string,object> Values(Entry e,IEnumerable<string> fields){return fields.ToDictionary(k=>k,k=>typeof(Entry).GetField(k).GetValue(e));}
  public static void Validate(){var allowed=new HashSet<string>(Core.Concat(Facets.Values.SelectMany(f=>f)));if(typeof(Entry).GetFields().Any(f=>!allowed.Contains(f.Name)))throw new InvalidDataException("资料字段尚未登记存储分面。");}
 }
 public sealed class LibraryStore {
  readonly string file;readonly VaultSession vault;DateTime lastBackup=DateTime.MinValue;public string FilePath{get{return file;}}
  public LibraryStore(string directory,VaultSession vault,string overridePath=null){this.vault=vault;file=overridePath??Path.Combine(directory,vault==null?"library.sqlite":"library.vault");}
  SqlDb Open(){return vault==null?new SqlDb(file):new SqlDb(":memory:",File.Exists(file)?vault.Unseal(File.ReadAllBytes(file),"library"):null);}
  static void Schema(SqlDb db){
   db.Exec("PRAGMA foreign_keys=ON");db.Exec("PRAGMA synchronous=FULL");db.Exec("PRAGMA secure_delete=ON");db.Exec("PRAGMA temp_store=MEMORY");
   db.Exec("CREATE TABLE IF NOT EXISTS meta(key TEXT PRIMARY KEY,value TEXT NOT NULL)");
   db.Exec("CREATE TABLE IF NOT EXISTS items(id TEXT PRIMARY KEY,kind TEXT NOT NULL,name TEXT NOT NULL,path TEXT NOT NULL,core TEXT NOT NULL)");
   db.Exec("CREATE TABLE IF NOT EXISTS facets(item_id TEXT NOT NULL REFERENCES items(id) ON DELETE CASCADE,module TEXT NOT NULL,version INTEGER NOT NULL DEFAULT 1,data TEXT NOT NULL,PRIMARY KEY(item_id,module))");
   db.Exec("CREATE TABLE IF NOT EXISTS objects(kind TEXT NOT NULL,id TEXT NOT NULL,data TEXT NOT NULL,PRIMARY KEY(kind,id))");
   db.Exec("CREATE TABLE IF NOT EXISTS operations(id TEXT PRIMARY KEY,data TEXT NOT NULL)");
   db.Exec("CREATE TABLE IF NOT EXISTS activity_days(day TEXT NOT NULL,item_id TEXT NOT NULL,data TEXT NOT NULL,PRIMARY KEY(day,item_id))");
   db.Exec("CREATE TABLE IF NOT EXISTS ai_cache(fingerprint TEXT PRIMARY KEY,module TEXT NOT NULL,data TEXT NOT NULL,created TEXT NOT NULL)");
   db.Exec("CREATE TABLE IF NOT EXISTS links(id TEXT PRIMARY KEY,source TEXT NOT NULL,target TEXT NOT NULL,kind TEXT NOT NULL,data TEXT NOT NULL)");
   db.Exec("CREATE INDEX IF NOT EXISTS link_source ON links(source,kind)");db.Exec("CREATE INDEX IF NOT EXISTS link_target ON links(target,kind)");
   db.Exec("CREATE TABLE IF NOT EXISTS contents(id TEXT PRIMARY KEY,body TEXT NOT NULL,stamp TEXT NOT NULL)");
   db.Exec("CREATE VIRTUAL TABLE IF NOT EXISTS search USING fts5(id UNINDEXED,name,body,tokenize='trigram')");
   bool rebuild=db.Query("SELECT name FROM sqlite_master WHERE type='table' AND name='content_search'").Count==0;
   db.Exec("CREATE VIRTUAL TABLE IF NOT EXISTS content_search USING fts5(id UNINDEXED,body,content='contents',content_rowid='rowid',tokenize='trigram')");
   db.Exec("INSERT INTO search(search,rank) VALUES('secure-delete',1)");db.Exec("INSERT INTO content_search(content_search,rank) VALUES('secure-delete',1)");
   db.Exec("CREATE TRIGGER IF NOT EXISTS content_insert AFTER INSERT ON contents BEGIN INSERT INTO content_search(rowid,id,body) VALUES(new.rowid,new.id,new.body); END");
   db.Exec("CREATE TRIGGER IF NOT EXISTS content_delete AFTER DELETE ON contents BEGIN INSERT INTO content_search(content_search,rowid,id,body) VALUES('delete',old.rowid,old.id,old.body); END");
   db.Exec("CREATE TRIGGER IF NOT EXISTS content_update AFTER UPDATE ON contents BEGIN INSERT INTO content_search(content_search,rowid,id,body) VALUES('delete',old.rowid,old.id,old.body); INSERT INTO content_search(rowid,id,body) VALUES(new.rowid,new.id,new.body); END");
   if(rebuild)db.Exec("INSERT INTO content_search(content_search) VALUES('rebuild')");db.Exec("PRAGMA user_version=1");
  }
  public bool Exists{get{return File.Exists(file);}}
  public void Initialize(Database data,bool fresh){if(vault!=null){Save(data,fresh);return;}string temp=file+".migrate-"+Guid.NewGuid().ToString("N");var staged=new LibraryStore(Path.GetDirectoryName(file),null,temp);staged.Save(data);if(staged.Load().items.Count!=data.items.Count)throw new InvalidDataException("资料库迁移校验失败，旧数据已保留。");File.Move(temp,file);}
  public Database Load(){using(var db=Open()){var integrity=db.Query("PRAGMA quick_check");if(integrity.Count!=1||integrity[0][0]!="ok")throw new InvalidDataException("资料库校验失败，原数据已保留。");var meta=db.Query("SELECT value FROM meta WHERE key='database'");if(meta.Count!=1)throw new InvalidDataException("资料库缺少核心数据，原数据已保留。");var result=Library.Json.Deserialize<Database>(meta[0][0]);var rows=db.Query("SELECT id,core FROM items").ToDictionary(r=>r[0],r=>Library.Json.Deserialize<Dictionary<string,object>>(r[1]));foreach(var f in db.Query("SELECT item_id,data FROM facets")){Dictionary<string,object> item;if(rows.TryGetValue(f[0],out item))foreach(var p in Library.Json.Deserialize<Dictionary<string,object>>(f[1]))item[p.Key]=p.Value;}result.items=rows.Values.Select(v=>Library.Json.Deserialize<Entry>(Library.Json.Serialize(v))).ToList();if(!Library.Json.Deserialize<Dictionary<string,object>>(meta[0][0]).ContainsKey("workspace")&&db.Query("SELECT name FROM sqlite_master WHERE type='table' AND name='objects'").Count>0){foreach(var row in db.Query("SELECT kind,data FROM objects")){if(row[0]=="space")result.workspace.spaces.Add(Library.Json.Deserialize<SpaceRecord>(row[1]));if(row[0]=="clip")result.workspace.clips.Add(Library.Json.Deserialize<ClipRecord>(row[1]));if(row[0]=="query")result.workspace.queries.Add(Library.Json.Deserialize<CollectionQuery>(row[1]));if(row[0]=="recipe")result.workspace.recipes.Add(Library.Json.Deserialize<RecipeRecord>(row[1]));}}result.operations=db.Query("SELECT data FROM operations ORDER BY rowid DESC LIMIT 512").Select(r=>Library.Json.Deserialize<Operation>(r[0])).Reverse().ToList();return result;}}
  static void Upsert(SqlDb db,string table,string key,string json){db.Exec("INSERT INTO "+table+"(id,data) VALUES(?,?) ON CONFLICT(id) DO UPDATE SET data=excluded.data",key,json);}
  public void Save(Database data,bool fresh=false,IEnumerable<string> itemIds=null,IEnumerable<string> operationIds=null,bool workspaceChanges=false){ItemShape.Validate();bool existed=Exists;using(var db=fresh&&vault!=null?new SqlDb(":memory:"):Open()){Schema(db);if(vault==null&&existed&&(!File.Exists(file+".bak")||DateTime.UtcNow-lastBackup>TimeSpan.FromMinutes(5))){db.Backup(file+".bak");lastBackup=DateTime.UtcNow;}db.Exec("BEGIN IMMEDIATE");try{
    var metadata=Library.Json.Deserialize<Dictionary<string,object>>(Library.Json.Serialize(new{data.version,data.settings,data.collections,data.fonts,data.watchFolders,data.ignoredAutoPaths}));db.Exec("INSERT INTO meta(key,value) VALUES('database',?) ON CONFLICT(key) DO UPDATE SET value=excluded.value",Library.Json.Serialize(metadata));
    var itemScope=itemIds==null?null:new HashSet<string>(itemIds);var selectedItems=data.items.Where(i=>itemScope==null||itemScope.Contains(i.id)).ToArray();var old=Scoped(db,"SELECT id,core FROM items","id",itemScope).ToDictionary(r=>r[0],r=>r[1]);var facetRows=Scoped(db,"SELECT item_id,module,data FROM facets","item_id",itemScope).ToDictionary(r=>r[0]+"|"+r[1],r=>r[2]);var searchRows=Scoped(db,"SELECT id,name,body FROM search","id",itemScope).ToDictionary(r=>r[0],r=>r);var present=new HashSet<string>(selectedItems.Select(i=>i.id));foreach(var id in old.Keys.Where(id=>!present.Contains(id))){db.Exec("DELETE FROM items WHERE id=?",id);db.Exec("DELETE FROM search WHERE id=?",id);db.Exec("DELETE FROM contents WHERE id=?",id);db.Exec("DELETE FROM links WHERE source=? OR target=?",id,id);}
    foreach(var item in selectedItems){string previousCore;if(old.TryGetValue(item.id,out previousCore)&&!String.IsNullOrEmpty(item.opened)){var earlier=Library.Json.Deserialize<Entry>(previousCore);if(earlier.opened!=item.opened||Math.Abs(earlier.progress-item.progress)>.0001){string day=DateTime.UtcNow.ToString("yyyy-MM-dd");db.Exec("INSERT INTO activity_days(day,item_id,data) VALUES(?,?,?) ON CONFLICT(day,item_id) DO UPDATE SET data=excluded.data",day,item.id,Library.Json.Serialize(new ReviewActivity{id=item.id,name=item.name,kind=item.kind,opened=DateTime.UtcNow.ToString("o"),progress=item.progress}));}}var core=Library.Json.Serialize(ItemShape.Values(item,ItemShape.Core));string previous;if(!old.TryGetValue(item.id,out previous)||previous!=core)db.Exec("INSERT INTO items(id,kind,name,path,core) VALUES(?,?,?,?,?) ON CONFLICT(id) DO UPDATE SET kind=excluded.kind,name=excluded.name,path=excluded.path,core=excluded.core",item.id,item.kind??"",item.name??"",item.path??"",core);
     foreach(var f in ItemShape.Facets){string json=Library.Json.Serialize(ItemShape.Values(item,f.Value));string prior;bool had=facetRows.TryGetValue(item.id+"|"+f.Key,out prior);if(json==Library.Json.Serialize(ItemShape.Values(new Entry(),f.Value))){if(had)db.Exec("DELETE FROM facets WHERE item_id=? AND module=?",item.id,f.Key);continue;}if(!had||prior!=json)db.Exec("INSERT INTO facets(item_id,module,data) VALUES(?,?,?) ON CONFLICT(item_id,module) DO UPDATE SET data=excluded.data",item.id,f.Key,json);}
     string body=SearchContent.Metadata(item);if(item.ownedDocument)db.Exec("DELETE FROM contents WHERE id=?",item.id);string[] previousSearch;if(!searchRows.TryGetValue(item.id,out previousSearch)||previousSearch[1]!=item.name||previousSearch[2]!=body){db.Exec("DELETE FROM search WHERE id=?",item.id);db.Exec("INSERT INTO search(id,name,body) VALUES(?,?,?)",item.id,item.name??"",body);}
    }
    if(itemScope==null||workspaceChanges){var objects=new Dictionary<string,string>();foreach(var group in new Dictionary<string,IEnumerable<object>>{{"space",data.workspace.spaces.Cast<object>()},{"clip",data.workspace.clips.Cast<object>()},{"query",data.workspace.queries.Cast<object>()},{"recipe",data.workspace.recipes.Cast<object>()}})foreach(var value in group.Value){var row=Library.Json.Deserialize<Dictionary<string,object>>(Library.Json.Serialize(value));string id=Convert.ToString(row["id"]);objects[group.Key+"|"+id]=Library.Json.Serialize(value);}var priorObjects=db.Query("SELECT kind,id,data FROM objects");foreach(var row in priorObjects)if(!objects.ContainsKey(row[0]+"|"+row[1]))db.Exec("DELETE FROM objects WHERE kind=? AND id=?",row[0],row[1]);foreach(var pair in objects){var key=pair.Key.Split('|');var oldObject=priorObjects.FirstOrDefault(r=>r[0]==key[0]&&r[1]==key[1]);if(oldObject==null||oldObject[2]!=pair.Value)db.Exec("INSERT INTO objects(kind,id,data) VALUES(?,?,?) ON CONFLICT(kind,id) DO UPDATE SET data=excluded.data",key[0],key[1],pair.Value);}
    }var opScope=new HashSet<string>(operationIds??data.operations.Select(o=>o.id));var history=Scoped(db,"SELECT id,data FROM operations","id",opScope).ToDictionary(r=>r[0],r=>r[1]);foreach(var op in (data.operations??new List<Operation>()).Where(o=>opScope.Contains(o.id))){string json=Library.Json.Serialize(op),before;if(!history.TryGetValue(op.id,out before)||before!=json)Upsert(db,"operations",op.id,json);}
    if(itemScope==null)db.Exec("DELETE FROM links WHERE kind IN ('collection','tag')");else foreach(var id in itemScope)db.Exec("DELETE FROM links WHERE source=? AND kind IN ('collection','tag')",id);foreach(var item in selectedItems){if(!String.IsNullOrEmpty(item.collection))Link(db,item.id,"collection:"+item.collection,"collection",null);foreach(var tag in item.tags??new List<string>())Link(db,item.id,"tag:"+tag,"tag",null);}if(itemScope==null||workspaceChanges){db.Exec("DELETE FROM links WHERE kind IN ('space','clip')");foreach(var edge in data.workspace.Links())Link(db,edge.source,edge.target,edge.kind,edge);}
    db.Exec("COMMIT");
   }catch{db.Exec("ROLLBACK");throw;}if(vault!=null)WriteEncrypted(db.Image());}
  }
  static List<string[]> Scoped(SqlDb db,string sql,string key,HashSet<string> ids){if(ids==null)return db.Query(sql);if(ids.Count==0)return new List<string[]>();var result=new List<string[]>();var values=ids.ToArray();for(int n=0;n<values.Length;n+=500){var chunk=values.Skip(n).Take(500).ToArray();result.AddRange(db.Query(sql+" WHERE "+key+" IN ("+String.Join(",",chunk.Select(v=>"?"))+")",chunk));}return result;}
  void WriteEncrypted(byte[] image){var temp=file+".tmp";File.WriteAllBytes(temp,vault.Seal(image,"library"));if(File.Exists(file))File.Replace(temp,file,file+".bak");else File.Move(temp,file);}
  internal static void Link(SqlDb db,string source,string target,string kind,object detail){string key=kind+":"+source+":"+target;db.Exec("INSERT INTO links(id,source,target,kind,data) VALUES(?,?,?,?,?) ON CONFLICT(id) DO UPDATE SET data=excluded.data",key,source,target,kind,Library.Json.Serialize(detail));}
  public void RefreshKnowledgeLinks(IEnumerable<string> sources,IEnumerable<KnowledgeLink> edges){using(var db=Open()){Schema(db);db.Exec("BEGIN IMMEDIATE");try{foreach(var source in sources)db.Exec("DELETE FROM links WHERE source=? AND kind IN ('link','tag')",source);foreach(var edge in edges)Link(db,edge.source,edge.target,edge.kind,edge);db.Exec("COMMIT");}catch{db.Exec("ROLLBACK");throw;}if(vault!=null)WriteEncrypted(db.Image());}}
  public List<KnowledgeLink> Relations(string itemId=null){using(var db=Open()){var rows=itemId==null?db.Query("SELECT source,target,kind,data FROM links ORDER BY id"):db.Query("SELECT source,target,kind,data FROM links WHERE source=? OR target=? ORDER BY id",itemId,itemId);return rows.Select(r=>r[3]!="null"?Library.Json.Deserialize<KnowledgeLink>(r[3]):new KnowledgeLink{source=r[0],target=r[1],kind=r[2],title=r[1].Contains(":")?r[1].Substring(r[1].IndexOf(':')+1):r[1]}).ToList();}}
  public List<string> Search(string query,int limit=0){query=(query??"").Trim();if(query.Length==0)return new List<string>();using(var db=Open()){Schema(db);string count=(limit>0?limit:-1).ToString();List<string[]> names,bodies;if(query.Length>=3){string phrase="\""+query.Replace("\"","\"\"")+"\"";names=db.Query("SELECT id FROM search WHERE search MATCH ? ORDER BY rank LIMIT ?",phrase,count);bodies=db.Query("SELECT id FROM content_search WHERE content_search MATCH ? ORDER BY rank LIMIT ?",phrase,count);}else{names=db.Query("SELECT id FROM search WHERE instr(lower(name),lower(?))>0 OR instr(lower(body),lower(?))>0 LIMIT ?",query,query,count);bodies=db.Query("SELECT id FROM contents WHERE instr(lower(body),lower(?))>0 LIMIT ?",query,count);}var ids=names.Concat(bodies).Select(r=>r[0]).Distinct();return (limit>0?ids.Take(limit):ids).ToList();}}
  public void Index(string id,string text,string stamp){using(var db=Open()){Schema(db);db.Exec("INSERT INTO contents(id,body,stamp) VALUES(?,?,?) ON CONFLICT(id) DO UPDATE SET body=excluded.body,stamp=excluded.stamp",id,text,stamp);if(vault!=null)WriteEncrypted(db.Image());}}
  public Entry ReadItem(string id){using(var db=Open()){var rows=db.Query("SELECT core FROM items WHERE id=?",id);if(rows.Count==0)return null;var value=Library.Json.Deserialize<Dictionary<string,object>>(rows[0][0]);foreach(var row in db.Query("SELECT data FROM facets WHERE item_id=?",id))foreach(var pair in Library.Json.Deserialize<Dictionary<string,object>>(row[0]))value[pair.Key]=pair.Value;return Library.Json.Deserialize<Entry>(Library.Json.Serialize(value));}}
  public List<Operation> OperationPage(int offset,int limit){using(var db=Open())return db.Query("SELECT data FROM operations ORDER BY rowid DESC LIMIT ? OFFSET ?",Math.Min(1000,limit).ToString(),Math.Max(0,offset).ToString()).Select(r=>Library.Json.Deserialize<Operation>(r[0])).Reverse().ToList();}
  public Operation Operation(string id){using(var db=Open()){var rows=db.Query("SELECT data FROM operations WHERE id=?",id);return rows.Count==0?null:Library.Json.Deserialize<Operation>(rows[0][0]);}}
  public List<Operation> AllOperations(){using(var db=Open())return db.Query("SELECT data FROM operations ORDER BY rowid").Select(r=>Library.Json.Deserialize<Operation>(r[0])).ToList();}
  internal void CompactAfterPrivateMove(IEnumerable<string> ids){
   if(vault!=null)throw new InvalidOperationException("仅普通资料库需要清理。");
   using(var db=Open()){Schema(db);db.Exec("BEGIN IMMEDIATE");try{
    foreach(var id in ids)db.Exec("DELETE FROM activity_days WHERE item_id=?",id);
    // Rebuild removes obsolete FTS segments from before secure-delete was enabled.
    db.Exec("INSERT INTO search(search) VALUES('rebuild')");db.Exec("INSERT INTO content_search(content_search) VALUES('rebuild')");db.Exec("COMMIT");
   }catch{db.Exec("ROLLBACK");throw;}
   db.Exec("VACUUM");
   string temp=file+".clean-backup";if(File.Exists(temp))File.Delete(temp);db.Backup(temp);
   if(File.Exists(file+".bak"))File.Replace(temp,file+".bak",null);else File.Move(temp,file+".bak");lastBackup=DateTime.UtcNow;
   }
  }
  public List<ReviewActivity> Activities(){using(var db=Open()){Schema(db);return db.Query("SELECT data FROM activity_days ORDER BY day DESC LIMIT 5000").Select(r=>Library.Json.Deserialize<ReviewActivity>(r[0])).ToList();}}
  public string CachedSummary(string fingerprint){using(var db=Open()){Schema(db);var rows=db.Query("SELECT data FROM ai_cache WHERE fingerprint=? AND module='recipe'",fingerprint);return rows.Count==0?null:rows[0][0];}}
  public void CacheSummary(string fingerprint,string text){using(var db=Open()){Schema(db);db.Exec("BEGIN IMMEDIATE");try{db.Exec("INSERT INTO ai_cache(fingerprint,module,data,created) VALUES(?,'recipe',?,?) ON CONFLICT(fingerprint) DO UPDATE SET data=excluded.data,created=excluded.created",fingerprint,text,DateTime.UtcNow.ToString("o"));db.Exec("DELETE FROM ai_cache WHERE module='recipe' AND fingerprint NOT IN (SELECT fingerprint FROM ai_cache WHERE module='recipe' ORDER BY created DESC LIMIT 64)");db.Exec("COMMIT");}catch{db.Exec("ROLLBACK");throw;}if(vault!=null)WriteEncrypted(db.Image());}}
  public object Info(){using(var db=Open())return new{engine="sqlite",schema=1,fts="fts5-trigram",items=db.Query("SELECT count(*) FROM items")[0][0],facets=db.Query("SELECT count(*) FROM facets")[0][0]};}
 }
}
